def validate_batch(batch):
    if not isinstance(batch, list):
        return {"ok": False, "error": "batch must be a list"}
    valid = []
    errors = []
    seen = []
    index = 0
    for element in batch:
        result = normalize_submission(element)
        if result["ok"]:
            record = result["record"]
            pair = (record["student"], record["assignment"])
            if pair not in seen:
                seen.append(pair)
                valid.append(record)
        else:
            errors.append({"index": index, "error": result["error"]})
        index = index + 1
    counts = {"total": len(batch), "valid": len(valid), "invalid": len(errors)}
    return {"ok": True, "valid": valid, "errors": errors, "counts": counts}

